            // `pending` itself is not drained, only `entry.name` is taken.
            // `providers-litellm` states the same at its flush site
            // (SMA-619).
            out.push(ModelEvent::ToolCallDelta {
                call_id,
                name: Some(name),
                args_delta: String::new(),
            });
        }
        out
